/* 把 GPIOA 恢复到上电默认状态 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA, ENABLE);
GPIO_DeInit(GPIOA);

/* 恢复调试口，救回被禁用 SWD 的芯片 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_AFIO, ENABLE);
GPIO_AFIODeInit();

GPIO_InitTypeDef GPIO_InitStructure;

/* 1. 先开时钟，这一步忘了后面全白配 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOC, ENABLE);

/* 2. 配置 PC13 为推挽输出，50MHz */
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_13;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_PP;
GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
GPIO_Init(GPIOC, &GPIO_InitStructure);

/* 3. 点亮（蓝板 LED 低电平点亮） */
GPIO_ResetBits(GPIOC, GPIO_Pin_13);

GPIO_InitTypeDef GPIO_InitStructure;

GPIO_StructInit(&GPIO_InitStructure);   /* 先填默认值 */
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_0;  /* 再改需要的字段 */
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IPU;
GPIO_Init(GPIOA, &GPIO_InitStructure);

/* 读取 PA0 按键，按下为低电平 */
if (GPIO_ReadInputDataBit(GPIOA, GPIO_Pin_0) == Bit_RESET)
{
  /* 按键按下 */
}

uint16_t portVal;

portVal = GPIO_ReadInputData(GPIOB);
if ((portVal & GPIO_Pin_5) != 0)
{
  /* PB5 为高电平 */
}

/* 翻转 PC13 的电平 */
if (GPIO_ReadOutputDataBit(GPIOC, GPIO_Pin_13) == Bit_SET)
{
  GPIO_ResetBits(GPIOC, GPIO_Pin_13);
}
else
{
  GPIO_SetBits(GPIOC, GPIO_Pin_13);
}

uint16_t oldVal = GPIO_ReadOutputData(GPIOB);
/* ... 临时改变 PB 口输出 ... */
GPIO_Write(GPIOB, oldVal);   /* 恢复原状态 */

/* 点亮共阳 LED（高电平点亮） */
GPIO_SetBits(GPIOC, GPIO_Pin_13);

/* 一次置高多个引脚 */
GPIO_SetBits(GPIOA, GPIO_Pin_0 | GPIO_Pin_1 | GPIO_Pin_2);

/* 用一个变量控制电平，不用写 if-else */
uint8_t level = 1;
GPIO_WriteBit(GPIOC, GPIO_Pin_13, (BitAction)level);

/* 或者直接传枚举 */
GPIO_WriteBit(GPIOC, GPIO_Pin_13, Bit_RESET);

/* 先把引脚配好，再锁定 */
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_5;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_PP;
GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
GPIO_Init(GPIOA, &GPIO_InitStructure);

GPIO_PinLockConfig(GPIOA, GPIO_Pin_5);   /* 锁定后不可改 */

RCC_APB2PeriphClockCmd(RCC_APB2Periph_AFIO, ENABLE);

/* 把事件输出放到 PA0 */
GPIO_EventOutputConfig(GPIO_PortSourceGPIOA, GPIO_PinSource0);
GPIO_EventOutputCmd(ENABLE);

/* 例1：释放 PA15/PB3/PB4，保留 SWD 下载能力 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_AFIO, ENABLE);
GPIO_PinRemapConfig(GPIO_Remap_SWJ_JTAGDisable, ENABLE);

/* 例2：USART1 重映射到 PB6/PB7 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_AFIO, ENABLE);
GPIO_PinRemapConfig(GPIO_Remap_USART1, ENABLE);

/* 用 PA0 做外部中断 */
GPIO_InitTypeDef GPIO_InitStructure;
EXTI_InitTypeDef EXTI_InitStructure;
NVIC_InitTypeDef NVIC_InitStructure;

RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_AFIO, ENABLE);

/* 1. 引脚配成上拉输入 */
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_0;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IPU;
GPIO_Init(GPIOA, &GPIO_InitStructure);

/* 2. 连到 EXTI0 线 */
GPIO_EXTILineConfig(GPIO_PortSourceGPIOA, GPIO_PinSource0);

/* 3. 配置 EXTI */
EXTI_InitStructure.EXTI_Line = EXTI_Line0;
EXTI_InitStructure.EXTI_Mode = EXTI_Mode_Interrupt;
EXTI_InitStructure.EXTI_Trigger = EXTI_Trigger_Falling;
EXTI_InitStructure.EXTI_LineCmd = ENABLE;
EXTI_Init(&EXTI_InitStructure);

/* 4. 使能 NVIC */
NVIC_InitStructure.NVIC_IRQChannel = EXTI0_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 0x01;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0x01;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);
